fn put64(out:[*]u8,slot:usize,value:i64)void{const bits:u64=@bitCast(value);for(0..8)|b|{out[slot*8+b]=@truncate(bits>>(b*8));}}
export fn highest_response_ratio_next(v:?[*]const i64,n:usize,out:[*c]u8,capacity:usize)i64{
 if(v==null||n<3||n>129)return -1;const input=v.?;const count=input[0];if(count<1||count>64||n!=1+2*@as(usize,@intCast(count)))return -1;var a=[_]i64{0}**64;var b=[_]i64{0}**64;var tat=[_]i64{0}**64;var done=[_]bool{false}**64;for(0..@intCast(count))|i|{a[i]=input[1+2*i];b[i]=input[2+2*i];if(a[i]<0 or a[i]>100000 or b[i]<1 or b[i]>1000)return -1;}for(1..@intCast(count))|i|{var j=i;while(j>0 and a[j]<a[j-1]){const ta=a[j];a[j]=a[j-1];a[j-1]=ta;const tb=b[j];b[j]=b[j-1];b[j-1]=tb;j-=1;}}if(@as(usize,@intCast(count))*8>capacity or(count>0 and out==null))return -2;var now:i64=0;var finished:usize=0;while(finished<@as(usize,@intCast(count))){var best:?usize=null;var best_num:i64=0;for(0..@intCast(count))|i|{if(!done[i] and a[i]<=now){const candidate=now-a[i]+b[i];if(best==null or candidate*b[best.?]>best_num*b[i]){best=i;best_num=candidate;}}}if(best==null){var earliest:?usize=null;for(0..@intCast(count))|i|{if(!done[i] and(earliest==null or a[i]<a[earliest.?]))earliest=i;}now=a[earliest.?];}else{const k=best.?;tat[k]=now+b[k]-a[k];now+=b[k];done[k]=true;finished+=1;}}for(0..@intCast(count))|i|{put64(out,i,tat[i]);}return count*8;
}
